join public.products product on product.merchant_id = m.id and product.asin = p->>'asin'
cross join lateral jsonb_array_elements_text(p->'sizes') as size(value)
where m.slug = 'amazombie'
on conflict (merchant_id, product_id, size) do nothing;

-- Seed the demo classifications explicitly; any unlisted field remains denied.
insert into public.data_classifications (merchant_id, resource, field_name, category)
select m.id, c.table_name, c.column_name,
  case when (c.table_name = 'merchants' and c.column_name in ('id', 'slug'))
         or (c.table_name = 'products' and c.column_name in (
           'id', 'merchant_id', 'asin', 'brand', 'name', 'short_name', 'color', 'pack_size',
           'fabric', 'fit', 'weight', 'default_size', 'sample_price_usd', 'price_basis',
           'rating', 'review_count', 'badge', 'image_path', 'source_url', 'highlights'))
         or (c.table_name = 'product_variants' and c.column_name in ('merchant_id', 'product_id', 'size')) then 'public'
       when c.table_name = 'supplier_costs' then 'private'
       when c.table_name in ('customer_profiles', 'carts', 'cart_items') then 'custodial'
       else 'reviewable' end
from public.merchants m
join information_schema.columns c on c.table_schema = 'public'
where m.slug = 'amazombie' and c.table_name in (
  'merchants', 'products', 'product_variants', 'inventory', 'product_measurements',
  'supplier_costs', 'customer_profiles', 'carts', 'cart_items')
on conflict (merchant_id, resource, field_name) do nothing;
